import{_ as s,C as n,o,c as d,a2 as r,b as l,w as e,a as i,E as h,a3 as p}from"./chunks/framework.BC3NdntU.js";const A=JSON.parse('{"title":"2.1 浏览器多进程架构","description":"","frontmatter":{},"headers":[],"relativePath":"卷二-浏览器工作原理/2.1-浏览器多进程架构.md","filePath":"卷二-浏览器工作原理/2.1-浏览器多进程架构.md","lastUpdated":1789034132000}'),u={name:"卷二-浏览器工作原理/2.1-浏览器多进程架构.md"};function c(b,t,E,m,g,B){const a=n("Mermaid");return o(),d("div",null,[t[1]||(t[1]=r('<h1 id="_2-1-浏览器多进程架构" tabindex="-1">2.1 浏览器多进程架构 <a class="header-anchor" href="#_2-1-浏览器多进程架构" aria-label="Permalink to &quot;2.1 浏览器多进程架构&quot;">​</a></h1><h2 id="引言-从-一页卡死全崩-到-多进程隔离" tabindex="-1">引言:从&quot;一页卡死全崩&quot;到&quot;多进程隔离&quot; <a class="header-anchor" href="#引言-从-一页卡死全崩-到-多进程隔离" aria-label="Permalink to &quot;引言:从&quot;一页卡死全崩&quot;到&quot;多进程隔离&quot;&quot;">​</a></h2><p>早期浏览器单进程:一个标签页崩溃整个浏览器全挂。现代 Chrome 改<strong>多进程 + 多线程</strong>,为稳定、安全、性能。要深挖,得懂 OS 层面的进程/线程,以及进程间怎么通信。</p><hr><h2 id="一、进程-vs-线程-os-层面" tabindex="-1">一、进程 vs 线程(OS 层面) <a class="header-anchor" href="#一、进程-vs-线程-os-层面" aria-label="Permalink to &quot;一、进程 vs 线程(OS 层面)&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th>进程</th><th>线程</th></tr></thead><tbody><tr><td>关系</td><td>资源分配最小单位</td><td>CPU 调度最小单位</td></tr><tr><td>内存</td><td>独立地址空间</td><td>共享所属进程内存</td></tr><tr><td>隔离</td><td>进程崩溃互不影响</td><td>线程崩溃可能拖垮进程</td></tr><tr><td>通信</td><td>需 IPC(进程间通信)</td><td>直接共享内存</td></tr></tbody></table><blockquote><p>进程是&quot;套房&quot;(隔音),线程是房里一起干活的&quot;人&quot;(共享客厅)。</p></blockquote><hr><h2 id="二、chrome-多进程模型" tabindex="-1">二、Chrome 多进程模型 <a class="header-anchor" href="#二、chrome-多进程模型" aria-label="Permalink to &quot;二、Chrome 多进程模型&quot;">​</a></h2>',9)),(o(),l(p,null,{default:e(()=>[h(a,{id:"mermaid-83",class:"mermaid",graph:"flowchart%20TD%0A%20%20%20%20A%5B%E6%B5%8F%E8%A7%88%E5%99%A8%E4%B8%BB%E8%BF%9B%E7%A8%8B%20Browser%3Cbr%2F%3E%E7%95%8C%E9%9D%A2%2F%E5%8D%8F%E8%B0%83%E8%B0%83%E5%BA%A6%5D%20--%3E%20B%5B%E7%BD%91%E7%BB%9C%E8%BF%9B%E7%A8%8B%5D%0A%20%20%20%20A%20--%3E%20C%5BGPU%20%E8%BF%9B%E7%A8%8B%5D%0A%20%20%20%20A%20--%3E%20D%5B%E6%B8%B2%E6%9F%93%E8%BF%9B%E7%A8%8B%20%C3%97%20N%3Cbr%2F%3E%E6%AF%8F%E6%A0%87%E7%AD%BE%E9%A1%B5%E4%B8%80%E4%B8%AA%2C%E6%B2%99%E7%AE%B1%5D%0A%20%20%20%20D%20--%3E%20D1%5B%E4%B8%BB%E7%BA%BF%E7%A8%8B%3A%E8%A7%A3%E6%9E%90%2FJS%2F%E5%B8%83%E5%B1%80%5D%0A%20%20%20%20D%20--%3E%20D2%5B%E5%90%88%E6%88%90%E7%BA%BF%E7%A8%8B%3A%E5%88%86%E5%B1%82%2F%E5%85%89%E6%A0%85%E5%8C%96%2F%E5%90%88%E6%88%90%5D%0A%20%20%20%20D%20--%3E%20D3%5B%E5%85%89%E6%A0%85%E5%8C%96%E7%BA%BF%E7%A8%8B%5D%0A%20%20%20%20D%20--%3E%20D4%5BWorker%20%E7%BA%BF%E7%A8%8B%5D%0A%20%20%20%20A%20-.-%3E%7CIPC%20%E8%BF%9B%E7%A8%8B%E9%97%B4%E9%80%9A%E4%BF%A1%7C%20D%0A"})]),fallback:e(()=>[...t[0]||(t[0]=[i(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=r(`<table tabindex="0"><thead><tr><th>进程</th><th>职责</th></tr></thead><tbody><tr><td>浏览器主进程</td><td>界面、地址栏、协调调度</td></tr><tr><td>渲染进程</td><td>解析 HTML/CSS/JS、绘制(每标签一个,沙箱)</td></tr><tr><td>GPU 进程</td><td>GPU 合成、光栅化加速</td></tr><tr><td>网络进程</td><td>统一网络请求</td></tr></tbody></table><hr><h2 id="三、为什么多进程-三个理由-代价" tabindex="-1">三、为什么多进程(三个理由 + 代价) <a class="header-anchor" href="#三、为什么多进程-三个理由-代价" aria-label="Permalink to &quot;三、为什么多进程(三个理由 + 代价)&quot;">​</a></h2><ol><li><strong>稳定</strong>:一渲染进程崩溃只影响那个标签页(崩溃隔离)</li><li><strong>安全</strong>:渲染进程跑在<strong>沙箱</strong>里,即使被攻破也拿不到系统权限、读不了别的进程内存</li><li><strong>性能</strong>:多核并行,GPU 独立进程加速合成</li></ol><p><strong>代价</strong>:内存占用更高(每个进程都有独立开销)。</p><p><strong>底层:进程间通信(IPC)</strong> 用 <strong>Mojo</strong>(Chrome 的 IPC 框架)在进程间传消息——渲染进程要发网络请求,是通过 IPC 转给网络进程,而非自己直接碰网络栈。这既是架构分层,也是安全边界。</p><hr><h2 id="四、渲染进程内部线程-为何主-合成分离" tabindex="-1">四、渲染进程内部线程(为何主/合成分离) <a class="header-anchor" href="#四、渲染进程内部线程-为何主-合成分离" aria-label="Permalink to &quot;四、渲染进程内部线程(为何主/合成分离)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>线程</th><th>职责</th></tr></thead><tbody><tr><td>主线程</td><td>解析、构建 DOM/CSSOM、执行 JS、布局——事件循环在此</td></tr><tr><td>合成线程</td><td>分层、分块、调度光栅化、合成位图(不碰 JS)</td></tr><tr><td>光栅化线程</td><td>指令转位图像素</td></tr><tr><td>Worker 线程</td><td>跑 Web Worker</td></tr></tbody></table><blockquote><p><strong>为什么主/合成要分线程?</strong> 主线程管&quot;逻辑重&quot;(解析/JS/布局),合成线程管&quot;像素重&quot;(光栅化/合成)。分离后合成可<strong>并行且不碰 JS</strong>——纯合成属性(transform/opacity)就能完全绕过主线程、不掉帧(2.5 的根基)。</p></blockquote><hr><h2 id="五、站点隔离-site-isolation" tabindex="-1">五、站点隔离(Site Isolation) <a class="header-anchor" href="#五、站点隔离-site-isolation" aria-label="Permalink to &quot;五、站点隔离(Site Isolation)&quot;">​</a></h2><p>不同&quot;站点(eTLD+1)&quot;分到不同渲染进程:跨站 iframe 隔离到独立进程,防 <strong>Spectre/Meltdown</strong> 侧信道攻击。代价:更多进程 = 更多内存。</p><hr><h2 id="六、小结" tabindex="-1">六、小结 <a class="header-anchor" href="#六、小结" aria-label="Permalink to &quot;六、小结&quot;">​</a></h2><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>多进程:主进程/网络/GPU/各标签渲染进程(沙箱),通过 Mojo IPC 通信</span></span>
<span class="line"><span>渲染进程多线程:主线程(逻辑布局)+ 合成(像素)+ 光栅化 + Worker</span></span>
<span class="line"><span>多进程意义:稳定(隔离)+ 安全(沙箱/站点隔离)+ 性能(并行)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p><strong>怎么亲眼看到这些进程:</strong></p><ol><li><strong>Chrome 任务管理器</strong>:<code>Shift + Esc</code>(或菜单 → 更多工具 → 任务管理器),能看到每个标签页对应的进程、内存、CPU</li><li><strong>系统任务管理器/活动监视器</strong>:能看到 Chrome 的多个进程(主进程、GPU、多个渲染进程)</li></ol><blockquote><p>验证:开 10 个不同网站标签,任务管理器里会看到 10+ 个渲染进程,内存总占用明显高于单进程浏览器——这就是&quot;多进程换稳定/安全&quot;的代价。</p></blockquote><hr><h2 id="七、面试题" tabindex="-1">七、面试题 <a class="header-anchor" href="#七、面试题" aria-label="Permalink to &quot;七、面试题&quot;">​</a></h2><p><strong>Q1:为什么浏览器要采用多进程模型?</strong></p><p>① 稳定(崩溃隔离);② 安全(渲染进程沙箱 + 站点隔离防侧信道);③ 性能(多核并行、GPU 独立)。代价是内存开销加大。</p><p><strong>Q2:一个标签页 JS 卡死,为什么不会卡死整个浏览器?为什么不会卡死同页的其他标签页?</strong></p><p>该页 JS 只在自己<strong>渲染进程的主线程</strong>跑,卡死的是这一个渲染进程;其他标签页各自独立进程照常响应。正是进程隔离的体现。(同进程内的多标签已被站点隔离尽量拆开。)</p><p><strong>Q3:渲染进程的主线程和合成线程为什么要分开?</strong></p><p>主线程管逻辑(解析/JS/布局),合成线程管像素(光栅化/合成)。分离后合成可并行、不碰 JS,<code>transform/opacity</code> 等纯合成属性就能完全绕过主线程,实现不掉帧动画(见 <a href="/frontend-knowledge-base/卷二-浏览器工作原理/2.5-合成与GPU加速.html">2.5</a>)。</p><p><strong>Q4:什么是&quot;沙箱&quot;?渲染进程的沙箱靠什么实现?</strong></p><p>沙箱是一种<strong>权限隔离机制</strong>:渲染进程只能做它被允许的事,无法直接访问系统资源(文件、网络栈大多受限)。靠 OS 的安全机制(如 Windows Job Object / macOS Seatbelt / Linux 命名空间与 seccomp)+ Chrome 的进程权限模型实现。</p><p><strong>Q5:既然多进程省心,为什么浏览器还要做&quot;进程复用/限制进程数&quot;?</strong></p><p>因为<strong>内存开销</strong>:每个渲染进程都有独立的基础内存。Chrome 会在内存紧张时<strong>合并/回收</strong>同站点的渲染进程,在&quot;隔离&quot;与&quot;内存&quot;间做权衡——这正是后台标签页会被&quot;冻结/丢弃&quot;的原因之一。</p><hr><p>📎 参考:Chrome Developers《Inside look at modern web browser》、Chromium 项目文档(Mojo / Site Isolation / Sandbox)</p><p>📎 权威延伸阅读:</p><ul><li>《Inside look at modern web browser》(Chrome Developers) <a href="https://developer.chrome.com/blog/inside-browser-part1/" target="_blank" rel="noreferrer">https://developer.chrome.com/blog/inside-browser-part1/</a></li><li>《Populating the page: how browsers work》(MDN) <a href="https://developer.mozilla.org/zh-CN/docs/Web/Performance/How_browsers_work" target="_blank" rel="noreferrer">https://developer.mozilla.org/zh-CN/docs/Web/Performance/How_browsers_work</a></li><li>《Multi-process Architecture》(Chromium) <a href="https://www.chromium.org/developers/design-documents/multi-process-architecture/" target="_blank" rel="noreferrer">https://www.chromium.org/developers/design-documents/multi-process-architecture/</a></li></ul>`,35))])}const _=s(u,[["render",c]]);export{A as __pageData,_ as default};
